55: impl rustix_kernel::paging::PageTableReader for LimineHhdmPageTableReader<'_> {
56:     type Error = rustix_kernel::memory::HhdmAddressError;
57: 
58:     fn read_entry(&self, table_physical: u64, index: u16) -> Result<u64, Self::Error> {
59:         if index >= 512 {
60:             return Err(rustix_kernel::memory::HhdmAddressError::InvalidHhdmRange);
61:         }
62:         let table_end = table_physical
63:             .checked_add(rustix_kernel::paging::PAGE_SIZE)
64:             .ok_or(rustix_kernel::memory::HhdmAddressError::AddressOverflow)?;
65:         if !self.memory_map.range_is_within_region_kind(
66:             table_physical,
67:             table_end,
68:             rustix_kernel::memory::RegionKind::BootloaderReclaimable,
69:         ) {
70:             return Err(rustix_kernel::memory::HhdmAddressError::NotLimineMapped);
71:         }
72:         let table_address = self.memory_map.limine_hhdm_address(
73:             self.hhdm_offset,
74:             table_physical,
75:             rustix_kernel::paging::PAGE_SIZE,
76:             Some(self.physical_address_bits),
77:             self.virtual_address_bits,
78:         )?;
79:         let entry_address = table_address
80:             .checked_add(u64::from(index) * core::mem::size_of::<u64>() as u64)
81:             .ok_or(rustix_kernel::memory::HhdmAddressError::AddressOverflow)?;
82:         // SAFETY: The complete table page was restricted to bootloader-reclaimable
83:         // memory and its HHDM address arithmetic was checked. The reader relies
84:         // on the Limine base-revision-3 mapping contract and never returns a ref.
85:         Ok(unsafe { (entry_address as *const u64).read_volatile() })
86:     }
87: }
