96: // SAFETY: `prepare_table` accepts only an allocator-issued frame and validates
97: // its complete usable span and HHDM address. Handles are only used while the
98: // candidate retains the frame token and this unique backend borrow.
99: unsafe impl rustix_kernel::paging::CandidatePageTableMemory for LimineHhdmCandidateMemory<'_> {
100:     type PreparedTable = u64;
101:     type Error = rustix_kernel::memory::HhdmAddressError;
102: 
103:     fn prepare_table(
104:         &mut self,
105:         frame: &rustix_kernel::frame::Frame,
106:     ) -> Result<Self::PreparedTable, Self::Error> {
107:         frame.hhdm_address(
108:             self.memory_map,
109:             self.hhdm_offset,
110:             Some(self.physical_address_bits),
111:             self.virtual_address_bits,
112:         )
113:     }
114: 
115:     unsafe fn read_entry(
116:         &self,
117:         table: Self::PreparedTable,
118:         index: u16,
119:     ) -> Result<u64, Self::Error> {
120:         if index >= 512 {
121:             return Err(rustix_kernel::memory::HhdmAddressError::InvalidHhdmRange);
122:         }
123:         let entry_address = table
124:             .checked_add(u64::from(index) * core::mem::size_of::<u64>() as u64)
125:             .ok_or(rustix_kernel::memory::HhdmAddressError::AddressOverflow)?;
126:         // SAFETY: The unsafe trait contract requires `table` to be the prepared
127:         // HHDM address of a complete writable frame; the index is in [0, 512).
128:         Ok(unsafe { (entry_address as *const u64).read_volatile() })
129:     }
130: 
131:     unsafe fn clear_table(&mut self, table: Self::PreparedTable) {
132:         let entries = table as *mut u64;
133:         // SAFETY: The caller provides a handle prepared by this backend for a
134:         // complete writable frame retained by its candidate.
135:         unsafe {
136:             for index in 0..512 {
137:                 entries.add(index).write_volatile(0);
138:             }
139:         }
140:     }
141: 
142:     unsafe fn write_entry(&mut self, table: Self::PreparedTable, index: u16, value: u64) {
143:         if index >= 512 {
144:             return;
145:         }
146:         let entry = (table as *mut u64).wrapping_add(usize::from(index));
147:         // SAFETY: The caller provides a prepared complete frame and an index in
148:         // range; this writes one entry without creating a Rust reference.
149:         unsafe { entry.write_volatile(value) };
150:     }
151: 
152:     unsafe fn invalidate_page(&mut self, virtual_address: u64) {
153:         // SAFETY: Active mapping callers provide the current virtual page and run
154:         // at CPL 0 with exclusive local page-table ownership.
155:         unsafe {
156:             core::arch::asm!(
157:                 "invlpg [{}]",
158:                 in(reg) virtual_address,
159:                 options(nostack, preserves_flags)
160:             );
161:         }
162:     }
163: }
