171: unsafe fn map_kernel_heap_pages(
172:     opaque_context: *mut (),
173:     first_page: usize,
174:     page_count: usize,
175: ) -> bool {
176:     use rustix_kernel::paging::{
177:         validate_mapping_range, CachePolicy, CandidatePageTables, EffectiveMemoryType, MtrrState,
178:         PagePermissions, PatLayout, PAGE_SIZE,
179:     };
180: 
181:     if page_count == 0
182:         || first_page
183:             .checked_add(page_count)
184:             .is_none_or(|end| end > KERNEL_HEAP_GROWTH_MAX_PAGES)
185:     {
186:         return false;
187:     }
188: 
189:     // SAFETY: The caller configures this callback only after the active root,
190:     // allocator, CPU snapshot, and local context are all live. The boot path is
191:     // single-vCPU and never returns from the stack containing that context.
192:     let state = unsafe { &mut *opaque_context.cast::<KernelHeapMappingContext>() };
193:     // SAFETY: These pointers refer to the retained local candidate and BootInfo
194:     // members. The callback is synchronous and never stores a derived reference.
195:     let candidate = unsafe {
196:         &mut *state
197:             .candidate
198:             .cast::<CandidatePageTables<'static, LimineHhdmCandidateMemory<'static>>>()
199:     };
200:     // SAFETY: The frame allocator and CPU snapshot remain owned by retained
201:     // BootInfo; this callback runs on the sole CPU with the heap lock held.
202:     let allocator = unsafe { &mut *state.allocator };
203:     // SAFETY: The CPU snapshot is immutable and remains live with BootInfo.
204:     let cpu_info = unsafe { &*state.cpu_info };
205: 
206:     let flags: u64;
207:     // SAFETY: The callback runs at CPL 0; save IF before disabling local IRQs
208:     // while the active page tables and allocator are mutated.
209:     unsafe { core::arch::asm!("pushfq", "pop {}", "cli", out(reg) flags) };
210:     let result = (|| {
211:         let physical_width = cpu_info.physical_address_bits?;
212:         let pat = PatLayout::from_msr_value(cpu_info.pat_msr_value?).ok()?;
213:         let mtrrs = match &cpu_info.mtrr {
214:             MtrrState::Captured(registers) => registers.validated_layout(physical_width).ok()?,
215:             _ => return None,
216:         };
217:         let permissions = PagePermissions {
218:             writable: true,
219:             executable: false,
220:             user_accessible: false,
221:         };
222:         let mut mapped = 0usize;
223:         for page in first_page..first_page + page_count {
224:             let virtual_address = KERNEL_HEAP_GROWTH_VIRTUAL_BASE
225:                 .checked_add((page as u64).checked_mul(PAGE_SIZE)?)?;
226:             let frame = match allocator.allocate() {
227:                 Some(frame) => frame,
228:                 None => {
229:                     rollback_kernel_heap_pages(candidate, allocator, first_page, mapped);
230:                     return None;
231:                 }
232:             };
233:             let mapping = match validate_mapping_range(
234:                 virtual_address,
235:                 frame.address(),
236:                 PAGE_SIZE,
237:                 permissions,
238:                 Some(physical_width),
239:                 cpu_info.active_linear_address_bits,
240:             ) {
241:                 Ok(mapping) => mapping,
242:                 Err(_) => {
243:                     deallocate_kernel_heap_frame(allocator, frame);
244:                     rollback_kernel_heap_pages(candidate, allocator, first_page, mapped);
245:                     return None;
246:                 }
247:             };
248:             let attributes = match mapping.select_cache_attributes(
249:                 CachePolicy::WriteBack,
250:                 pat,
251:                 &mtrrs,
252:                 cpu_info.normal_caching,
253:             ) {
254:                 Ok(attributes) if attributes.effective_type() == EffectiveMemoryType::WriteBack => {
255:                     attributes
256:                 }
257:                 _ => {
258:                     deallocate_kernel_heap_frame(allocator, frame);
259:                     rollback_kernel_heap_pages(candidate, allocator, first_page, mapped);
260:                     return None;
261:                 }
262:             };
263:             // SAFETY: IF is clear, the current candidate owns the active root,
264:             // and the allocator-issued frame is mapped RW/NX with local TLB
265:             // invalidation before its token becomes page-table-owned.
266:             if let Err(failure) =
267:                 unsafe { candidate.map_owned_page_active(allocator, frame, mapping, attributes) }
268:             {
269:                 deallocate_kernel_heap_frame(allocator, failure.frame);
270:                 rollback_kernel_heap_pages(candidate, allocator, first_page, mapped);
271:                 return None;
272:             }
273:             mapped += 1;
274:         }
275:         Some(())
276:     })()
277:     .is_some();
278:     if flags & (1 << 9) != 0 {
279:         // SAFETY: The mapping transaction is complete or fully rolled back.
280:         unsafe { core::arch::asm!("sti") };
281:     }
282:     result
283: }
