285: fn rollback_kernel_heap_pages(
286:     candidate: &mut rustix_kernel::paging::CandidatePageTables<
287:         'static,
288:         LimineHhdmCandidateMemory<'static>,
289:     >,
290:     allocator: &mut rustix_kernel::frame::FrameAllocator,
291:     first_page: usize,
292:     mapped_pages: usize,
293: ) {
294:     use rustix_kernel::paging::PAGE_SIZE;
295: 
296:     for page in (first_page..first_page + mapped_pages).rev() {
297:         let virtual_address = KERNEL_HEAP_GROWTH_VIRTUAL_BASE + page as u64 * PAGE_SIZE;
298:         // SAFETY: The pages belong to this transaction in the current active
299:         // root; unmapping invalidates their TLB entries before token return.
300:         let frame = unsafe { candidate.unmap_owned_page_active(virtual_address) }
301:             .unwrap_or_else(|_| halt_forever());
302:         deallocate_kernel_heap_frame(allocator, frame);
303:     }
304: }
