358: // The legacy-reserved authorization is accepted only for RSDP reads; all
359: // root and child tables require ACPI-reclaimable/NVS memory-map coverage.
360: impl CandidateAcpiReader<'_, '_, '_> {
361:     fn read_mapped(
362:         &mut self,
363:         physical_start: u64,
364:         output: &mut [u8],
365:         allow_legacy_rsdp: bool,
366:     ) -> Result<(), AcpiMappingError> {
367:         use rustix_kernel::paging::{
368:             validate_mapping_range, CachePolicy, PagePermissions, PageWalkOutcome, PAGE_SIZE,
369:         };
370: 
371:         if arch::x86_64::cpu::read_cr3_raw() != self.previous_cr3 {
372:             return Err(AcpiMappingError::UnexpectedCurrentCr3);
373:         }
374:         if output.is_empty() {
375:             return Ok(());
376:         }
377:         let length =
378:             u64::try_from(output.len()).map_err(|_| AcpiMappingError::InvalidAcpiSpan {
379:                 physical_start,
380:                 length: output.len(),
381:                 error: rustix_kernel::memory::AcpiSpanError::AddressOverflow,
382:             })?;
383:         let span = if allow_legacy_rsdp {
384:             self.memory_map.validate_rsdp_span(
385:                 physical_start,
386:                 length,
387:                 Some(self.physical_address_bits),
388:             )
389:         } else {
390:             self.memory_map.validate_acpi_span(
391:                 physical_start,
392:                 length,
393:                 Some(self.physical_address_bits),
394:             )
395:         }
396:         .map_err(|error| AcpiMappingError::InvalidAcpiSpan {
397:             physical_start,
398:             length: output.len(),
399:             error,
400:         })?;
401:         let permissions = PagePermissions {
402:             writable: false,
403:             executable: false,
404:             user_accessible: false,
405:         };
406:         let mut copied = 0usize;
407:         while copied < output.len() {
408:             let current_physical = physical_start.checked_add(copied as u64).ok_or(
409:                 AcpiMappingError::InvalidAcpiSpan {
410:                     physical_start,
411:                     length: output.len(),
412:                     error: rustix_kernel::memory::AcpiSpanError::AddressOverflow,
413:                 },
414:             )?;
415:             let physical_page = current_physical & !(PAGE_SIZE - 1);
416:             let page_offset = current_physical - physical_page;
417:             let page_length = (PAGE_SIZE - page_offset).min((output.len() - copied) as u64);
418:             let mapping = validate_mapping_range(
419:                 self.virtual_address,
420:                 physical_page,
421:                 PAGE_SIZE,
422:                 permissions,
423:                 Some(self.physical_address_bits),
424:                 self.virtual_address_bits,
425:             )
426:             .map_err(AcpiMappingError::InvalidMapping)?;
427:             let cache_attributes = mapping
428:                 .select_cache_attributes(
429:                     CachePolicy::Uncacheable,
430:                     self.pat,
431:                     &self.cache_layout,
432:                     self.normal_caching,
433:                 )
434:                 .map_err(AcpiMappingError::InvalidMapping)?;
435:             self.candidate
436:                 .map_acpi_page(self.allocator, span, mapping, cache_attributes)
437:                 .map_err(|failure| AcpiMappingError::CandidateMap(failure.cause))?;
438: 
439:             let candidate_mapping_is_valid = matches!(
440:                 self.candidate.walk(self.virtual_address),
441:                 Ok(PageWalkOutcome::Mapped(translation))
442:                     if translation.physical_address == physical_page
443:                         && translation.permissions == permissions
444:             );
445:             if !candidate_mapping_is_valid {
446:                 self.remove_temporary_mapping();
447:                 return Err(AcpiMappingError::CandidateWalk);
448:             }
449:             if arch::x86_64::cpu::read_cr3_raw() != self.previous_cr3 {
450:                 halt_forever();
451:             }
452: 
453:             // SAFETY: The candidate is a complete clone of the current inherited
454:             // hierarchy with all critical paths verified; this temporary page is
455:             // supervisor R/NX and the candidate remains owned by this stack.
456:             unsafe { arch::x86_64::cpu::write_cr3_with_global_flush(self.candidate_cr3) };
457:             // SAFETY: The CR3 write above installed the candidate root and maskable
458:             // interrupts remain disabled during this single-core bootstrap read.
459:             unsafe { self.candidate.mark_active() };
460:             if arch::x86_64::cpu::read_cr3_raw() != self.candidate_cr3 {
461:                 // SAFETY: Restoring the previous validated root preserves all code,
462:                 // stack, data, and exception mappings needed by this path.
463:                 unsafe { arch::x86_64::cpu::write_cr3_with_global_flush(self.previous_cr3) };
464:                 if arch::x86_64::cpu::read_cr3_raw() != self.previous_cr3 {
465:                     halt_forever();
466:                 }
467:                 // SAFETY: The verified CR3 is no longer the candidate root.
468:                 unsafe { self.candidate.mark_inactive() };
469:                 self.remove_temporary_mapping();
470:                 return Err(AcpiMappingError::UnexpectedCurrentCr3);
471:             }
472: 
473:             let source = (self.virtual_address + page_offset) as *const u8;
474:             for offset in 0..page_length as usize {
475:                 // SAFETY: The exact physical page is temporarily mapped R/NX in
476:                 // the active candidate and this byte lies within its 4 KiB leaf.
477:                 output[copied + offset] = unsafe { source.add(offset).read_volatile() };
478:             }
479: 
480:             // SAFETY: The prior root remains allocated and its critical mappings
481:             // were verified before this temporary switch.
482:             unsafe { arch::x86_64::cpu::write_cr3_with_global_flush(self.previous_cr3) };
483:             if arch::x86_64::cpu::read_cr3_raw() != self.previous_cr3 {
484:                 halt_forever();
485:             }
486:             // SAFETY: The previous root was restored and verified above.
487:             unsafe { self.candidate.mark_inactive() };
488:             self.remove_temporary_mapping();
489:             copied += page_length as usize;
490:         }
491:         Ok(())
492:     }
493: }
