557: fn activate_cloned_page_tables_and_run(boot_info: &mut boot::BootInfo) -> ! {
558:     use rustix_kernel::paging::{
559:         encode_cr3_value, CandidatePageTables, PageWalkConfig, PageWalkOutcome, PAGE_SIZE,
560:     };
561: 
562:     let physical_address_bits = match boot_info.cpu_info.physical_address_bits {
563:         Some(bits) => bits,
564:         None => {
565:             kprintln!("page-table transition rejected: physical width unknown");
566:             halt_forever();
567:         }
568:     };
569:     let inherited_root = match boot_info.inherited_cr3_root {
570:         Ok(root) => root,
571:         Err(error) => {
572:             kprintln!("page-table transition rejected: inherited CR3: {:?}", error);
573:             halt_forever();
574:         }
575:     };
576:     if !boot_info.cpu_info.nx_enabled {
577:         kprintln!("page-table transition rejected: NXE is not enabled");
578:         halt_forever();
579:     }
580:     let config = PageWalkConfig {
581:         levels: if boot_info.cpu_info.active_linear_address_bits == 57 {
582:             5
583:         } else {
584:             4
585:         },
586:         physical_address_bits,
587:         virtual_address_bits: boot_info.cpu_info.active_linear_address_bits,
588:         nx_enabled: boot_info.cpu_info.nx_enabled,
589:         page_2m_supported: true,
590:         page_1g_supported: boot_info.cpu_info.has_1g_pages,
591:     };
592:     let reader = LimineHhdmPageTableReader {
593:         memory_map: &boot_info.memory_map,
594:         hhdm_offset: boot_info.hhdm_offset,
595:         physical_address_bits,
596:         virtual_address_bits: boot_info.cpu_info.active_linear_address_bits,
597:     };
598:     let mut memory = LimineHhdmCandidateMemory {
599:         memory_map: &boot_info.memory_map,
600:         hhdm_offset: boot_info.hhdm_offset,
601:         physical_address_bits,
602:         virtual_address_bits: boot_info.cpu_info.active_linear_address_bits,
603:     };
604:     let mut candidate =
605:         match CandidatePageTables::new(&mut boot_info.frame_allocator, &mut memory, config) {
606:             Ok(candidate) => candidate,
607:             Err(error) => {
608:                 kprintln!(
609:                     "page-table transition failed to create root: {:?}",
610:                     error.cause
611:                 );
612:                 if let Some(frame) = error.frame {
613:                     release_probe_frame(&mut boot_info.frame_allocator, frame);
614:                 }
615:                 halt_forever();
616:             }
617:         };
618:     if let Err(error) =
619:         candidate.clone_inherited_hierarchy(&mut boot_info.frame_allocator, &reader, inherited_root)
620:     {
621:         kprintln!(
622:             "page-table transition failed to clone inherited root: {:?}",
623:             error
624:         );
625:         release_candidate_after_probe_failure(candidate, &mut boot_info.frame_allocator);
626:     }
627: 
628:     let segments = boot_info.kernel_image_segments;
629:     let spans = [
630:         (
631:             "kernel text",
632:             segments.text.virtual_start,
633:             segments.text.physical_start,
634:             segments.text.virtual_end - segments.text.virtual_start,
635:         ),
636:         (
637:             "kernel rodata",
638:             segments.rodata.virtual_start,
639:             segments.rodata.physical_start,
640:             segments.rodata.virtual_end - segments.rodata.virtual_start,
641:         ),
642:         (
643:             "kernel data",
644:             segments.data.virtual_start,
645:             segments.data.physical_start,
646:             segments.data.virtual_end - segments.data.virtual_start,
647:         ),
648:         (
649:             "active boot stack",
650:             boot_info.boot_stack_virtual_start,
651:             boot_info.boot_stack_physical_start,
652:             boot_info.boot_stack_virtual_end - boot_info.boot_stack_virtual_start,
653:         ),
654:     ];
655:     for (label, virtual_start, physical_start, length) in spans {
656:         if !candidate_span_matches_source(
657:             &candidate,
658:             &reader,
659:             inherited_root,
660:             config,
661:             virtual_start,
662:             physical_start,
663:             length,
664:         ) {
665:             kprintln!(
666:                 "page-table transition rejected: {} was not preserved",
667:                 label
668:             );
669:             release_candidate_after_probe_failure(candidate, &mut boot_info.frame_allocator);
670:         }
671:     }
672:     if !harden_kernel_hhdm_aliases(
673:         &mut candidate,
674:         &mut boot_info.frame_allocator,
675:         &boot_info.memory_map,
676:         boot_info.hhdm_offset,
677:         boot_info.cpu_info.physical_address_bits,
678:         boot_info.cpu_info.active_linear_address_bits,
679:         boot_info.kernel_image_segments,
680:         &reader,
681:         inherited_root,
682:         config,
683:     ) {
684:         release_candidate_after_probe_failure(candidate, &mut boot_info.frame_allocator);
685:     }
686:     kprintln!("kernel HHDM aliases validated: text/rodata R/NX, data RW/NX, PAT preserved");
687:     let candidate_root = candidate
688:         .root_physical_address()
689:         .expect("a live candidate retains its root frame");
690:     let root_hhdm_address = match boot_info.memory_map.limine_hhdm_address(
691:         boot_info.hhdm_offset,
692:         candidate_root,
693:         rustix_kernel::paging::PAGE_SIZE,
694:         Some(physical_address_bits),
695:         boot_info.cpu_info.active_linear_address_bits,
696:     ) {
697:         Ok(address) => address,
698:         Err(error) => {
699:             kprintln!(
700:                 "page-table transition rejected: candidate root HHDM: {:?}",
701:                 error
702:             );
703:             release_candidate_after_probe_failure(candidate, &mut boot_info.frame_allocator);
704:         }
705:     };
706:     let root_alias = match candidate.walk(root_hhdm_address) {
707:         Ok(PageWalkOutcome::Mapped(translation))
708:             if translation.physical_address == candidate_root =>
709:         {
710:             translation
711:         }
712:         result => {
713:             kprintln!(
714:                 "page-table transition rejected: candidate root HHDM alias: {:?}",
715:                 result
716:             );
717:             release_candidate_after_probe_failure(candidate, &mut boot_info.frame_allocator);
718:         }
719:     };
720:     if !root_alias.permissions.writable || root_alias.permissions.user_accessible {
721:         kprintln!("page-table transition rejected: candidate root alias permissions are unsafe");
722:         release_candidate_after_probe_failure(candidate, &mut boot_info.frame_allocator);
723:     }
724: 
725:     let new_cr3 = match encode_cr3_value(
726:         candidate_root,
727:         inherited_root.low_bits(),
728:         physical_address_bits,
729:     ) {
730:         Ok(value) => value,
731:         Err(error) => {
732:             kprintln!("page-table transition rejected: new CR3: {:?}", error);
733:             release_candidate_after_probe_failure(candidate, &mut boot_info.frame_allocator);
734:         }
735:     };
736:     let inherited_cr3 = boot_info.inherited_cr3_raw;
737:     if arch::x86_64::cpu::read_cr3_raw() != inherited_cr3 {
738:         kprintln!("page-table transition aborted: active CR3 changed before switch");
739:         release_candidate_after_probe_failure(candidate, &mut boot_info.frame_allocator);
740:     }
741:     if let Some(rsdp_physical_address) = boot_info.rsdp_physical_address {
742:         match load_acpi_madt(
743:             &mut candidate,
744:             &mut boot_info.frame_allocator,
745:             &boot_info.memory_map,
746:             &boot_info.cpu_info,
747:             rsdp_physical_address,
748:             new_cr3,
749:             inherited_cr3,
750:         ) {
751:             Ok(madt) => {
752:                 kprintln!(
753:                     "ACPI MADT copied: LAPIC={:#x}, {} local APICs, {} I/O APICs, {} overrides",
754:                     madt.local_apic_address,
755:                     madt.local_apics().count(),
756:                     madt.io_apics().count(),
757:                     madt.interrupt_overrides().count()
758:                 );
759:                 boot_info.acpi_madt = Some(madt);
760:             }
761:             Err(error) => kprintln!("ACPI MADT unavailable: {:?}", error),
762:         }
763:     }
764:     let apic_virtual_addresses = match boot_info.acpi_madt.as_ref() {
765:         Some(madt) => match map_bootstrap_apic_pages(
766:             &mut candidate,
767:             &mut boot_info.frame_allocator,
768:             &boot_info.cpu_info,
769:             madt,
770:         ) {
771:             Ok(addresses) => Some(addresses),
772:             Err(error) => {
773:                 kprintln!("APIC MMIO mappings unavailable: {}", error);
774:                 None
775:             }
776:         },
777:         None => None,
778:     };
779:     // SAFETY: The candidate is a complete clone of every present inherited
780:     // hierarchy entry, with all referenced intermediate tables owned and the
781:     // critical code/data/stack paths compared before this point. The inherited
782:     // root's paging mode, address widths, PAT/MTRR state, and low CR3 mode are
783:     // preserved; interrupts remain disabled through this transition and are enabled
784:     // later only after the selected APIC routes and handlers are ready.
785:     let global_tlb_flushed = unsafe { arch::x86_64::cpu::write_cr3_with_global_flush(new_cr3) };
786:     if global_tlb_flushed {
787:         kprintln!("page-table transition: global TLB flushed via CR4.PGE toggle");
788:     } else {
789:         kprintln!("page-table transition: CR4.PGE clear; CR3 reload flushed active translations");
790:     }
791:     if arch::x86_64::cpu::read_cr3_raw() != new_cr3
792:         || !spans
793:             .iter()
794:             .all(|(_, virtual_start, physical_start, length)| {
795:                 candidate_span_matches_source(
796:                     &candidate,
797:                     &reader,
798:                     inherited_root,
799:                     config,
800:                     *virtual_start,
801:                     *physical_start,
802:                     *length,
803:                 )
804:             })
805:     {
806:         // SAFETY: The inherited root and its backing memory remain untouched and
807:         // mapped by the candidate, so restoring its validated CR3 value is safe.
808:         unsafe { arch::x86_64::cpu::write_cr3_with_global_flush(inherited_cr3) };
809:         if arch::x86_64::cpu::read_cr3_raw() != inherited_cr3 {
810:             kprintln!("page-table transition failed to restore inherited CR3; candidate retained");
811:             halt_forever();
812:         }
813:         kprintln!("page-table transition failed post-switch verification; restored inherited CR3");
814:         release_candidate_after_probe_failure(candidate, &mut boot_info.frame_allocator);
815:     }
816:     // SAFETY: CR3 matches `new_cr3` and post-switch translation checks passed;
817:     // interrupts are disabled and the candidate root must remain allocated.
818:     unsafe { candidate.mark_active() };
819:     kprintln!(
820:         "page-table transition passed: active CR3={:#x}, cloned root={:#x}, {} owned tables",
821:         new_cr3,
822:         candidate_root,
823:         candidate.table_count()
824:     );
825: 
826:     #[cfg(feature = "probe-active-mapping")]
827:     {
828:         if let Err(error) = probe_active_mapping(
829:             &mut candidate,
830:             &mut boot_info.frame_allocator,
831:             &boot_info.cpu_info,
832:         ) {
833:             kprintln!("active mapping probe failed: {}", error);
834:             halt_forever();
835:         }
836:         kprintln!("active mapping probe passed: mapped, accessed, unmapped, reclaimed frame");
837:     }
838: 
839:     let mut vector_allocator = rustix_kernel::irq::InterruptVectorAllocator::new();
840:     let mut timer_vector = None;
841:     let mut timer_verified = false;
842:     if let (Some(madt), Some((local_apic_virtual, io_apic_virtual))) =
843:         (boot_info.acpi_madt.as_ref(), apic_virtual_addresses)
844:     {
845:         if let Some(vector) = vector_allocator.allocate() {
846:             let vector_number = vector.number();
847:             timer_vector = Some(vector);
848:             // SAFETY: Boot is single-core with IF=0. The cloned root is active,
849:             // and these virtual addresses were validated supervisor RW/NX/UC
850:             // mappings of the exact MADT-described APIC pages.
851:             match unsafe {
852:                 arch::x86_64::apic::initialize(
853:                     madt,
854:                     local_apic_virtual,
855:                     io_apic_virtual,
856:                     arch::x86_64::cpu::bootstrap_apic_id(),
857:                 )
858:             } {
859:                 Err(error) => kprintln!(
860:                     "APIC initialization failed; IRQs remain disabled: {:?}",
861:                     error
862:                 ),
863:                 Ok(()) => {
864:                     // SAFETY: APIC initialization masked every route, including
865:                     // PIT IRQ0; the handler is ready before the route is armed.
866:                     match unsafe {
867:                         arch::x86_64::interrupts::register_irq_handler(
868:                             vector_number,
869:                             bootstrap_timer_irq,
870:                         )
871:                     } {
872:                         Err(error) => {
873:                             kprintln!("timer IRQ handler registration failed: {:?}", error)
874:                         }
875:                         Ok(()) => match PitRate::for_frequency(100) {
876:                             Err(error) => kprintln!("PIT rate selection failed: {:?}", error),
877:                             Ok(rate) => {
878:                                 // SAFETY: The source remains masked through
879:                                 // configuration and the ISR is already registered.
880:                                 let configured = unsafe {
881:                                     arch::x86_64::apic::configure_pit_timer(
882:                                         vector_number,
883:                                         rate.divisor(),
884:                                     )
885:                                 };
886:                                 match configured {
887:                                     Err(error) => {
888:                                         kprintln!("PIT configuration failed: {:?}", error)
889:                                     }
890:                                     Ok(()) => {
891:                                         // SAFETY: Only the validated IRQ0 route is
892:                                         // unmasked after its handler is installed.
893:                                         match unsafe { arch::x86_64::apic::unmask_pit_timer() } {
894:                                             Err(error) => {
895:                                                 kprintln!("PIT route unmask failed: {:?}", error)
896:                                             }
897:                                             Ok(()) => {
898:                                                 // SAFETY: IDT/APIC/EOI/handler are
899:                                                 // ready, every other route is masked,
900:                                                 // and this ISR neither allocates nor
901:                                                 // touches non-atomic shared state.
902:                                                 unsafe {
903:                                                     core::arch::asm!(
904:                                                         "sti",
905:                                                         options(nomem, nostack)
906:                                                     );
907:                                                 }
908:                                                 let target =
909:                                                     BOOTSTRAP_TIMER_TICKS.ticks().saturating_add(3);
910:                                                 let mut observed = false;
911:                                                 for _ in 0..100_000_000 {
912:                                                     if BOOTSTRAP_TIMER_TICKS.ticks() >= target {
913:                                                         observed = true;
914:                                                         break;
915:                                                     }
916:                                                     spin_loop();
917:                                                 }
918:                                                 if observed {
919:                                                     timer_verified = true;
920:                                                     kprintln!("timer IRQ path passed: 3 ticks, EOI acknowledged");
921:                                                 } else {
922:                                                     // SAFETY: Stop the sole unmasked
923:                                                     // source before continuing without
924:                                                     // a verified runtime clock.
925:                                                     unsafe {
926:                                                         core::arch::asm!(
927:                                                             "cli",
928:                                                             options(nomem, nostack)
929:                                                         );
930:                                                         let _ =
931:                                                             arch::x86_64::apic::mask_pit_timer();
932:                                                     }
933:                                                     kprintln!("timer IRQ validation timed out; interrupts disabled");
934:                                                 }
935:                                             }
936:                                         }
937:                                     }
938:                                 }
939:                             }
940:                         },
941:                     }
942:                 }
943:             }
944:         } else {
945:             kprintln!("no device IRQ vector available; interrupts remain disabled");
946:         }
947:     } else {
948:         kprintln!("validated MADT/APIC mappings unavailable; polling mode retained");
949:     }
950:     let input_irq_flags: u64;
951:     // SAFETY: Route setup and callback registration require IF=0.
952:     unsafe { core::arch::asm!("pushfq", "pop {}", "cli", out(reg) input_irq_flags) };
953:     let input_setup = if timer_verified {
954:         boot_info
955:             .acpi_madt
956:             .as_ref()
957:             .map(|madt| configure_input_irqs(madt, &mut vector_allocator))
958:             .unwrap_or_default()
959:     } else {
960:         InputIrqSetup::default()
961:     };
962:     if input_irq_flags & (1 << 9) != 0 {
963:         // SAFETY: Device handlers and masked-first routes are initialized.
964:         unsafe { core::arch::asm!("sti") };
965:     }
966:     let _keep_vector_allocator_and_token_live = (
967:         vector_allocator,
968:         timer_vector,
969:         input_setup.uart_vector,
970:         input_setup.keyboard_vector,
971:     );
972:     let mut heap_mapping_context = KernelHeapMappingContext {
973:         candidate: core::ptr::addr_of_mut!(candidate).cast(),
974:         allocator: core::ptr::addr_of_mut!(boot_info.frame_allocator),
975:         cpu_info: core::ptr::addr_of!(boot_info.cpu_info),
976:     };
977:     for page in 0..KERNEL_HEAP_GROWTH_MAX_PAGES {
978:         let address = KERNEL_HEAP_GROWTH_VIRTUAL_BASE + page as u64 * PAGE_SIZE;
979:         if !matches!(
980:             candidate.walk(address),
981:             Ok(PageWalkOutcome::NotPresent { .. })
982:         ) {
983:             kprintln!(
984:                 "frame-backed heap virtual range is already mapped at {:#x}",
985:                 address
986:             );
987:             halt_forever();
988:         }
989:     }
990:     // SAFETY: The full virtual range is confirmed unmapped and exclusively
991:     // reserved. Candidate, allocator, CPU snapshot, and context remain live on
992:     // this non-returning boot path; the callback is transactional and nonallocating.
993:     if let Err(error) = unsafe {
994:         KERNEL_HEAP.initialize_frame_backed_region(
995:             KERNEL_HEAP_GROWTH_VIRTUAL_BASE as usize,
996:             KERNEL_HEAP_GROWTH_MAX_PAGES,
997:             core::ptr::addr_of_mut!(heap_mapping_context).cast(),
998:             map_kernel_heap_pages,
999:         )
1000:     } {
1001:         kprintln!("frame-backed heap setup failed: {:?}", error);
1002:         halt_forever();
1003:     }
1004:     kprintln!(
1005:         "frame-backed heap configured: {} KiB maximum, demand-mapped",
1006:         KERNEL_HEAP_GROWTH_MAX_PAGES * PAGE_SIZE as usize / 1024
1007:     );
1008:     #[cfg(feature = "probe-kernel-threads")]
1009:     if timer_verified {
1010:         if let Err(error) = kernel_threads::smoke(
1011:             &mut candidate,
1012:             &mut boot_info.frame_allocator,
1013:             &boot_info.cpu_info,
1014:             &BOOTSTRAP_TIMER_TICKS,
1015:         ) {
1016:             kprintln!("cooperative thread probe failed: {}", error);
1017:             halt_forever();
1018:         }
1019:     }
1020:     probe_kernel_heap();
1021: 
1022:     // Keep the candidate and its frame tokens alive for as long as this root is
1023:     // active. The shell runs forever and does not return to this stack frame.
1024:     // SAFETY: The bootstrap remains single-core. If enabled, the timer handler
1025:     // touches only its atomic counter and APIC EOI; the shell owns the filesystem.
1026:     let filesystem = unsafe { &mut *core::ptr::addr_of_mut!(RAM_FILESYSTEM) };
1027:     match filesystem.seed_defaults() {
1028:         Ok(home) if input_setup.uart_ready && timer_verified => {
1029:             let mut shell_context = ShellThreadContext {
1030:                 filesystem: core::ptr::addr_of_mut!(*filesystem),
1031:                 cwd: home,
1032:                 memory_map: core::ptr::addr_of!(boot_info.memory_map),
1033:                 frame_allocator: core::ptr::addr_of!(boot_info.frame_allocator),
1034:             };
1035:             // SAFETY: The active root, candidate tokens, allocator, BootInfo,
1036:             // filesystem, and callback context remain live on this non-returning
1037:             // single-vCPU path. The allocator pointer stays raw between calls.
1038:             kernel_threads::run_shell(
1039:                 &mut candidate,
1040:                 core::ptr::addr_of_mut!(boot_info.frame_allocator),
1041:                 &boot_info.cpu_info,
1042:                 &BOOTSTRAP_TIMER_TICKS,
1043:                 shell_thread_entry,
1044:                 core::ptr::addr_of_mut!(shell_context) as usize,
1045:             )
1046:         }
1047:         Ok(home) => shell::run(
1048:             filesystem,
1049:             home,
1050:             &boot_info.memory_map,
1051:             core::ptr::addr_of!(boot_info.frame_allocator),
1052:             core::ptr::null_mut(),
1053:         ),
1054:         Err(error) => {
1055:             kprintln!("RAM filesystem initialization failed: {:?}", error);
1056:             halt_forever()
1057:         }
1058:     }
1059: }
