1061: extern "C" fn bootstrap_timer_irq() {
1062:     BOOTSTRAP_TIMER_TICKS.tick();
1063:     // Acknowledge before a scheduling switch so the APIC does not retain an
1064:     // in-service timer vector while another context runs.
1065:     arch::x86_64::apic::end_of_interrupt();
1066:     kernel_threads::timer_interrupt();
1067: }
