1069: #[derive(Default)]
1070: struct InputIrqSetup {
1071:     uart_vector: Option<rustix_kernel::irq::InterruptVector>,
1072:     keyboard_vector: Option<rustix_kernel::irq::InterruptVector>,
1073:     uart_ready: bool,
1074:     keyboard_ready: bool,
1075: }
1076: 
1077: fn configure_input_irqs(
1078:     madt: &rustix_kernel::acpi::Madt,
1079:     vectors: &mut rustix_kernel::irq::InterruptVectorAllocator,
1080: ) -> InputIrqSetup {
1081:     let mut setup = InputIrqSetup::default();
1082:     if let Some((vector, route_ready)) =
1083:         configure_one_input_irq(madt, vectors, 4, arch::x86_64::serial::irq_handler)
1084:     {
1085:         let vector_number = vector.number();
1086:         setup.uart_vector = Some(vector);
1087:         if route_ready && arch::x86_64::serial::enable_receive_interrupts() {
1088:             // SAFETY: The UART handler is installed, COM1 is initialized, and
1089:             // only its previously masked MADT route is being unmasked.
1090:             setup.uart_ready =
1091:                 unsafe { arch::x86_64::apic::unmask_isa_irq(4, vector_number).is_ok() };
1092:             if !setup.uart_ready {
1093:                 arch::x86_64::serial::disable_receive_interrupts();
1094:             }
1095:         }
1096:     }
1097: 
1098:     if let Some((vector, route_ready)) =
1099:         configure_one_input_irq(madt, vectors, 1, arch::x86_64::keyboard::irq_handler)
1100:     {
1101:         let vector_number = vector.number();
1102:         setup.keyboard_vector = Some(vector);
1103:         if route_ready && arch::x86_64::keyboard::initialize_interrupts() {
1104:             // SAFETY: The bounded PS/2 controller setup succeeded and its
1105:             // registered IRQ handler is ready before unmasking the route.
1106:             setup.keyboard_ready =
1107:                 unsafe { arch::x86_64::apic::unmask_isa_irq(1, vector_number).is_ok() };
1108:         }
1109:     }
1110:     kprintln!(
1111:         "interrupt-driven input: UART RX {}, PS/2 raw scancodes {}",
1112:         if setup.uart_ready {
1113:             "ready"
1114:         } else {
1115:             "unavailable"
1116:         },
1117:         if setup.keyboard_ready {
1118:             "ready"
1119:         } else {
1120:             "unavailable"
1121:         }
1122:     );
1123:     setup
1124: }
1125: 
1126: fn configure_one_input_irq(
1127:     madt: &rustix_kernel::acpi::Madt,
