495: // SAFETY: `read_mapped` authorizes ordinary table reads only through validated
496: // ACPI map regions; its separate RSDP entry point permits only the bounded legacy
497: // reserved window recognized by `MemoryMap::validate_rsdp_span`.
498: unsafe impl rustix_kernel::acpi::AcpiPhysicalReader for CandidateAcpiReader<'_, '_, '_> {
499:     type Error = AcpiMappingError;
500: 
501:     fn read(&mut self, physical_start: u64, output: &mut [u8]) -> Result<(), Self::Error> {
502:         self.read_mapped(physical_start, output, false)
503:     }
504: 
505:     fn read_rsdp(&mut self, physical_start: u64, output: &mut [u8]) -> Result<(), Self::Error> {
506:         self.read_mapped(physical_start, output, true)
507:     }
508: }
509: 
510: // Capture Limine's entry RSP before a Rust prologue changes it. The synthetic
511: // return slot is part of the SysV entry stack; realign before calling Rust.
512: core::arch::global_asm!(
513:     ".section .text",
514:     ".code64",
515:     ".global _start",
516:     ".type _start, @function",
517:     "_start:",
518:     "mov rdi, rsp",
519:     "and rsp, -16",
520:     "call rustix_start",
521:     "ud2",
522:     ".size _start, . - _start",
523: );
524: 
525: #[no_mangle]
526: pub extern "C" fn rustix_start(entry_rsp: u64) -> ! {
527:     // Keep interrupts masked until FPU state and the IRQ save destination are ready.
528:     unsafe { core::arch::asm!("cli", options(nomem, nostack)) };
529:     arch::x86_64::serial::initialize();
530:     if let Err(error) = arch::x86_64::cpu::initialize_fpu_state() {
531:         kprintln!("required x87/SSE state unavailable: {:?}", error);
532:         halt_forever();
533:     }
534:     kernel_threads::initialize_fpu_context();
535:     kprintln!("Rustix kernel: x86_64 Rust bootstrap");
536:     kprintln!("x87/SSE context state enabled with FXSAVE/FXRSTOR; AVX disabled");
537:     arch::x86_64::interrupts::initialize();
538:     kprintln!("x86_64 exception diagnostics: enabled (IRQs remain disabled)");
539:     let mut boot_info = match boot::capture_boot_information(entry_rsp) {
540:         Ok(boot_info) => boot_info,
541:         Err(error) => {
542:             kprintln!("boot information rejected: {:?}", error);
543:             halt_forever();
544:         }
545:     };
546:     boot::report_boot_information(&boot_info);
547: 
548:     #[cfg(feature = "probe-hhdm-frame")]
549:     probe_hhdm_frame(&mut boot_info);
550: 
551:     #[cfg(any(feature = "inject-page-fault", feature = "inject-invalid-opcode"))]
552:     run_fault_injection();
553: 
554:     activate_cloned_page_tables_and_run(&mut boot_info)
555: }
