1126: fn configure_one_input_irq(
1127:     madt: &rustix_kernel::acpi::Madt,
1128:     vectors: &mut rustix_kernel::irq::InterruptVectorAllocator,
1129:     isa_irq: u8,
1130:     handler: arch::x86_64::interrupts::IrqHandler,
1131: ) -> Option<(rustix_kernel::irq::InterruptVector, bool)> {
1132:     let vector = vectors.allocate()?;
1133:     let vector_number = vector.number();
1134:     // SAFETY: This function is called with IF=0. The device route is masked
1135:     // until both the APIC redirection and its callback are installed.
1136:     if unsafe { arch::x86_64::interrupts::register_irq_handler(vector_number, handler) }.is_err() {
1137:         let _ = vectors.release(vector);
1138:         return None;
1139:     }
1140:     // SAFETY: `madt` is the validated owned table used for APIC initialization;
1141:     // its route is kept masked until the device and handler are ready.
1142:     if unsafe { arch::x86_64::apic::configure_isa_irq(madt, isa_irq, vector_number) }.is_err() {
1143:         kprintln!(
1144:             "ISA IRQ{} route configuration failed; source remains masked",
1145:             isa_irq
1146:         );
1147:         return Some((vector, false));
1148:     }
1149:     Some((vector, true))
1150: }
