1530:                 }
1531:             };
1532:             let source = match walk_virtual_address(reader, inherited_root, alias, config) {
1533:                 Ok(PageWalkOutcome::Mapped(translation)) => translation,
1534:                 result => {
1535:                     kprintln!(
1536:                         "kernel HHDM alias check failed: {} inherited walk: {:?}",
1537:                         label,
1538:                         result
1539:                     );
1540:                     return false;
1541:                 }
1542:             };
1543:             let permissions = PagePermissions {
1544:                 writable,
1545:                 executable: false,
1546:                 user_accessible: false,
1547:             };
1548:             if let Err(error) = candidate.set_inherited_page_permissions(
1549:                 allocator,
1550:                 alias,
1551:                 physical_address,
1552:                 permissions,
1553:             ) {
1554:                 kprintln!(
1555:                     "kernel HHDM alias check failed: {} protection: {:?}",
1556:                     label,
1557:                     error
1558:                 );
1559:                 return false;
1560:             }
1561:             match candidate.walk(alias) {
1562:                 Ok(PageWalkOutcome::Mapped(translation))
1563:                     if translation.physical_address == physical_address
1564:                         && translation.permissions == permissions
1565:                         && translation.pat_index == source.pat_index => {}
1566:                 result => {
1567:                     kprintln!(
1568:                         "kernel HHDM alias check failed: {} candidate walk: {:?}",
1569:                         label,
1570:                         result
1571:                     );
1572:                     return false;
1573:                 }
1574:             }
1575:             offset += PAGE_SIZE;
1576:         }
1577:     }
1578:     true
1579: }
