1581: fn probe_kernel_heap() {
1582:     use core::alloc::{GlobalAlloc, Layout};
1583:     use rustix_kernel::paging::PAGE_SIZE;
1584: 
1585:     let full_layout = match Layout::from_size_align(rustix_kernel::heap::KERNEL_HEAP_CAPACITY, 1) {
1586:         Ok(layout) => layout,
1587:         Err(error) => {
1588:             kprintln!(
1589:                 "kernel heap probe failed to construct full-arena layout: {:?}",
1590:                 error
1591:             );
1592:             halt_forever();
1593:         }
1594:     };
1595:     // SAFETY: The heap static is initialized before use and maskable interrupts
1596:     // remain disabled; this probe requests a valid nonzero layout.
1597:     let full_arena = unsafe { KERNEL_HEAP.alloc(full_layout) };
1598:     if full_arena.is_null() {
1599:         kprintln!("kernel heap probe failed: full-arena allocation was rejected");
1600:         halt_forever();
1601:     }
1602:     let oversized_layout =
1603:         match Layout::from_size_align(KERNEL_HEAP_GROWTH_MAX_PAGES * PAGE_SIZE as usize + 1, 1) {
1604:             Ok(layout) => layout,
1605:             Err(_) => halt_forever(),
1606:         };
1607:     // SAFETY: The request is larger than either bounded arena and must fail.
1608:     let exhausted = unsafe { KERNEL_HEAP.alloc(oversized_layout) };
1609:     if !exhausted.is_null() {
1610:         // SAFETY: Both pointers are live allocations with their original layouts.
1611:         unsafe {
1612:             KERNEL_HEAP.dealloc(exhausted, oversized_layout);
1613:             KERNEL_HEAP.dealloc(full_arena, full_layout);
1614:         }
1615:         kprintln!("kernel heap probe failed: bounded growth exhaustion was not deterministic");
1616:         halt_forever();
1617:     }
1618:     // SAFETY: `full_arena` is the complete live allocation created above.
1619:     unsafe { KERNEL_HEAP.dealloc(full_arena, full_layout) };
1620: 
1621:     let layout = match Layout::from_size_align(257, 64) {
1622:         Ok(layout) => layout,
1623:         Err(error) => {
1624:             kprintln!(
1625:                 "kernel heap probe failed to construct aligned layout: {:?}",
1626:                 error
1627:             );
1628:             halt_forever();
1629:         }
1630:     };
1631:     // SAFETY: The heap is available after releasing the full-arena allocation.
1632:     let allocation = unsafe { KERNEL_HEAP.alloc(layout) };
1633:     if allocation.is_null() || allocation as usize % layout.align() != 0 {
1634:         if !allocation.is_null() {
1635:             // SAFETY: This is the live allocation returned for `layout`.
1636:             unsafe { KERNEL_HEAP.dealloc(allocation, layout) };
1637:         }
1638:         kprintln!("kernel heap probe failed: aligned allocation was rejected or misaligned");
1639:         halt_forever();
1640:     }
1641:     let Some(allocation) = core::ptr::NonNull::new(allocation) else {
1642:         kprintln!("kernel heap probe failed: aligned allocation was unexpectedly null");
1643:         halt_forever();
1644:     };
1645:     // SAFETY: The allocator returned `layout.size()` writable bytes.
1646:     unsafe { core::ptr::write_bytes(allocation.as_ptr(), 0xa5, layout.size()) };
1647:     for index in 0..layout.size() {
1648:         // SAFETY: `index` remains inside the live allocation.
1649:         if unsafe { allocation.as_ptr().add(index).read_volatile() } != 0xa5 {
1650:             // SAFETY: The allocation is still live with its original layout.
1651:             unsafe { KERNEL_HEAP.dealloc(allocation.as_ptr(), layout) };
1652:             kprintln!("kernel heap probe failed: allocation data did not round-trip");
1653:             halt_forever();
1654:         }
1655:     }
1656:     // SAFETY: The allocation is live and the original layout is supplied.
1657:     unsafe { KERNEL_HEAP.dealloc(allocation.as_ptr(), layout) };
1658:     // SAFETY: The previous allocation was returned; first-fit should reuse it.
1659:     let reused = unsafe { KERNEL_HEAP.alloc(layout) };
1660:     if reused != allocation.as_ptr() {
1661:         if !reused.is_null() {
1662:             // SAFETY: `reused` is a live allocation with `layout`.
1663:             unsafe { KERNEL_HEAP.dealloc(reused, layout) };
1664:         }
1665:         kprintln!("kernel heap probe failed: freed space was not reused");
1666:         halt_forever();
1667:     }
1668:     // SAFETY: The reused allocation is live and has the same layout.
1669:     unsafe { KERNEL_HEAP.dealloc(reused, layout) };
1670: 
1671:     let growth_layout = match Layout::from_size_align(
1672:         rustix_kernel::heap::KERNEL_HEAP_CAPACITY + PAGE_SIZE as usize,
1673:         64,
1674:     ) {
1675:         Ok(layout) => layout,
1676:         Err(_) => halt_forever(),
1677:     };
1678:     // SAFETY: This request is larger than the bootstrap arena, so it must use
1679:     // the configured frame-backed range and remain within its fixed limit.
1680:     let growth = unsafe { KERNEL_HEAP.alloc(growth_layout) };
1681:     let Some(growth) = core::ptr::NonNull::new(growth) else {
1682:         kprintln!("kernel heap probe failed: frame-backed allocation was rejected");
1683:         halt_forever();
1684:     };
1685:     let growth_address = growth.as_ptr() as usize;
1686:     let growth_end = KERNEL_HEAP_GROWTH_VIRTUAL_BASE as usize
1687:         + KERNEL_HEAP_GROWTH_MAX_PAGES * PAGE_SIZE as usize;
1688:     if growth_address < KERNEL_HEAP_GROWTH_VIRTUAL_BASE as usize
1689:         || growth_address
1690:             .checked_add(growth_layout.size())
1691:             .is_none_or(|end| end > growth_end)
1692:         || growth_address % growth_layout.align() != 0
1693:     {
1694:         // SAFETY: `growth` is the live allocation returned for `growth_layout`.
1695:         unsafe { KERNEL_HEAP.dealloc(growth.as_ptr(), growth_layout) };
1696:         kprintln!("kernel heap probe failed: frame-backed allocation was invalid");
1697:         halt_forever();
1698:     }
1699:     // SAFETY: GlobalAlloc returned a live allocation, and the checks above keep
1700:     // its complete extent inside the reserved range. The heap mapper commits all
1701:     // pages covering the allocation before returning it. MaybeUninit permits the
1702:     // backing frames to be uninitialized when the mutable view is created.
1703:     let growth_bytes = unsafe {
1704:         core::slice::from_raw_parts_mut(
1705:             growth.as_ptr().cast::<core::mem::MaybeUninit<u8>>(),
1706:             growth_layout.size(),
1707:         )
1708:     };
1709:     let last_byte = growth_layout.size() - 1;
1710:     growth_bytes[0].write(0x5a);
1711:     growth_bytes[last_byte].write(0xa5);
1712:     // SAFETY: Both slots were initialized immediately above and are within the
1713:     // validated live allocation. Reading through the references retains the
1714:     // allocation's validity proof for the volatile access.
1715:     let first_byte = unsafe { growth_bytes[0].assume_init_ref() };
1716:     let last_byte = unsafe { growth_bytes[last_byte].assume_init_ref() };
1717:     if unsafe { core::ptr::read_volatile(first_byte) } != 0x5a
1718:         || unsafe { core::ptr::read_volatile(last_byte) } != 0xa5
1719:     {
1720:         // SAFETY: The allocation is still live with its original layout.
1721:         unsafe { KERNEL_HEAP.dealloc(growth.as_ptr(), growth_layout) };
1722:         kprintln!("kernel heap probe failed: frame-backed data did not round-trip");
1723:         halt_forever();
1724:     }
1725:     // SAFETY: Return the exact growth allocation and then require first-fit reuse.
1726:     unsafe { KERNEL_HEAP.dealloc(growth.as_ptr(), growth_layout) };
1727:     let growth_reused = unsafe { KERNEL_HEAP.alloc(growth_layout) };
1728:     if growth_reused != growth.as_ptr() {
1729:         if !growth_reused.is_null() {
1730:             // SAFETY: The pointer is live with `growth_layout`.
1731:             unsafe { KERNEL_HEAP.dealloc(growth_reused, growth_layout) };
1732:         }
1733:         kprintln!("kernel heap probe failed: frame-backed space was not reused");
1734:         halt_forever();
1735:     }
1736:     // SAFETY: Release the reused allocation with its original layout.
1737:     unsafe { KERNEL_HEAP.dealloc(growth_reused, growth_layout) };
1738:     kprintln!("kernel heap probe passed: bootstrap exhaustion, frame-backed growth, reuse");
1739: }
