1741: #[cfg(feature = "probe-hhdm-frame")]
1742: fn probe_hhdm_frame(boot_info: &mut boot::BootInfo) {
1743:     use rustix_kernel::frame::FRAME_SIZE;
1744: 
1745:     let frame = match boot_info.frame_allocator.allocate() {
1746:         Some(frame) => frame,
1747:         None => {
1748:             kprintln!("HHDM frame probe failed: no free frame");
1749:             halt_forever();
1750:         }
1751:     };
1752:     let hhdm_address = match frame.hhdm_address(
1753:         &boot_info.memory_map,
1754:         boot_info.hhdm_offset,
1755:         boot_info.cpu_info.physical_address_bits,
1756:         boot_info.cpu_info.active_linear_address_bits,
1757:     ) {
1758:         Ok(address) => address,
1759:         Err(error) => {
1760:             kprintln!("HHDM frame probe rejected frame translation: {:?}", error);
1761:             release_probe_frame(&mut boot_info.frame_allocator, frame);
1762:             halt_forever();
1763:         }
1764:     };
1765: 
1766:     let words = (FRAME_SIZE / core::mem::size_of::<u64>() as u64) as usize;
1767:     let page = hhdm_address as *mut u64;
1768:     let mut verified = true;
1769:     // SAFETY: The non-copyable `Frame` token is held exclusively; its full page
1770:     // is within validated `Usable` memory and its HHDM arithmetic was checked.
1771:     // Limine base revision 3 guarantees usable memory in the HHDM, and no other
1772:     // Rustix mapping aliases this newly allocated frame. This is an opt-in QEMU
1773:     // probe; a broken loader mapping would fault and be caught by the fatal path.
1774:     unsafe {
1775:         for index in 0..words {
1776:             page.add(index)
1777:                 .write_volatile(0xa5a5_0000_0000_0000 ^ index as u64);
1778:         }
1779:         for index in 0..words {
1780:             if page.add(index).read_volatile() != (0xa5a5_0000_0000_0000 ^ index as u64) {
1781:                 verified = false;
1782:                 break;
1783:             }
1784:         }
1785:         for index in 0..words {
1786:             page.add(index).write_volatile(0);
1787:         }
1788:     }
1789: 
1790:     release_probe_frame(&mut boot_info.frame_allocator, frame);
1791:     if !verified {
1792:         kprintln!("HHDM frame probe failed: readback mismatch");
1793:         halt_forever();
1794:     }
1795:     kprintln!("HHDM frame probe passed: wrote, read, cleared, and reclaimed one frame");
1796:     probe_inherited_root(boot_info);
1797: }
