1800: fn probe_inherited_root(boot_info: &mut boot::BootInfo) {
1801:     use rustix_kernel::paging::inherited_cr3_root_hhdm_address;
1802: 
1803:     let root = match boot_info.inherited_cr3_root {
1804:         Ok(root) => root,
1805:         Err(error) => {
1806:             kprintln!(
1807:                 "inherited root probe failed: CR3 decode rejected: {:?}",
1808:                 error
1809:             );
1810:             halt_forever();
1811:         }
1812:     };
1813:     let address = match inherited_cr3_root_hhdm_address(
1814:         root,
1815:         &boot_info.memory_map,
1816:         boot_info.hhdm_offset,
1817:         boot_info.cpu_info.physical_address_bits,
1818:         boot_info.cpu_info.active_linear_address_bits,
1819:     ) {
1820:         Ok(address) => address,
1821:         Err(error) => {
1822:             kprintln!(
1823:                 "inherited root probe failed: HHDM validation rejected: {:?}",
1824:                 error
1825:             );
1826:             halt_forever();
1827:         }
1828:     };
1829:     let entries = address as *const u64;
1830:     let mut present_entries = 0;
1831:     // SAFETY: The complete root page was validated as bootloader-reclaimable
1832:     // and its HHDM range arithmetic was checked. The Limine base-revision-3
1833:     // contract maps that region; this read-only opt-in probe trusts that handoff.
1834:     unsafe {
1835:         for index in 0..512 {
1836:             if entries.add(index).read_volatile() & 1 != 0 {
1837:                 present_entries += 1;
1838:             }
1839:         }
1840:     }
1841:     kprintln!(
1842:         "inherited root HHDM probe passed: read 512 entries, {} present",
1843:         present_entries
1844:     );
1845:     let physical_address_bits = match boot_info.cpu_info.physical_address_bits {
1846:         Some(bits) => bits,
1847:         None => {
1848:             kprintln!("inherited page-table walk failed: physical width unknown");
1849:             halt_forever();
1850:         }
1851:     };
1852:     let reader = LimineHhdmPageTableReader {
1853:         memory_map: &boot_info.memory_map,
1854:         hhdm_offset: boot_info.hhdm_offset,
1855:         physical_address_bits,
1856:         virtual_address_bits: boot_info.cpu_info.active_linear_address_bits,
1857:     };
1858:     let config = rustix_kernel::paging::PageWalkConfig {
1859:         levels: if boot_info.cpu_info.active_linear_address_bits == 57 {
1860:             5
1861:         } else {
1862:             4
1863:         },
1864:         physical_address_bits,
1865:         virtual_address_bits: boot_info.cpu_info.active_linear_address_bits,
1866:         nx_enabled: boot_info.cpu_info.nx_enabled,
1867:         page_2m_supported: true,
1868:         page_1g_supported: boot_info.cpu_info.has_1g_pages,
1869:     };
1870:     let segments = boot_info.kernel_image_segments;
1871:     verify_inherited_mapping(
1872:         &reader,
1873:         root,
1874:         config,
1875:         "kernel text",
1876:         segments.text.virtual_start,
1877:         segments.text.physical_start,
1878:         segments.text.virtual_end - segments.text.virtual_start,
1879:     );
1880:     verify_inherited_mapping(
1881:         &reader,
1882:         root,
1883:         config,
1884:         "kernel rodata",
1885:         segments.rodata.virtual_start,
1886:         segments.rodata.physical_start,
1887:         segments.rodata.virtual_end - segments.rodata.virtual_start,
1888:     );
1889:     verify_inherited_mapping(
1890:         &reader,
1891:         root,
1892:         config,
1893:         "kernel data",
1894:         segments.data.virtual_start,
1895:         segments.data.physical_start,
1896:         segments.data.virtual_end - segments.data.virtual_start,
1897:     );
1898:     verify_inherited_mapping(
1899:         &reader,
1900:         root,
1901:         config,
1902:         "active boot stack",
1903:         boot_info.boot_stack_virtual_start,
1904:         boot_info.boot_stack_physical_start,
1905:         boot_info.boot_stack_virtual_end - boot_info.boot_stack_virtual_start,
1906:     );
1907: 
1908:     let pat_value = match boot_info.cpu_info.pat_msr_value {
1909:         Some(value) => value,
1910:         None => {
1911:             kprintln!("cache-alias probe failed: active PAT value unavailable");
1912:             halt_forever();
1913:         }
1914:     };
1915:     let pat = match rustix_kernel::paging::PatLayout::from_msr_value(pat_value) {
1916:         Ok(pat) => pat,
1917:         Err(error) => {
1918:             kprintln!("cache-alias probe failed: invalid PAT layout: {:?}", error);
1919:             halt_forever();
1920:         }
1921:     };
1922:     let registers = match &boot_info.cpu_info.mtrr {
1923:         rustix_kernel::paging::MtrrState::Captured(registers) => registers,
1924:         _ => {
1925:             kprintln!("cache-alias probe failed: captured MTRR state unavailable");
1926:             halt_forever();
1927:         }
1928:     };
1929:     let mtrrs = match registers.validated_layout(physical_address_bits) {
1930:         Ok(mtrrs) => mtrrs,
1931:         Err(error) => {
1932:             kprintln!("cache-alias probe failed: invalid MTRR state: {:?}", error);
1933:             halt_forever();
1934:         }
1935:     };
1936:     if !boot_info.cpu_info.normal_caching {
1937:         kprintln!("cache-alias probe failed: non-normal CR0 caching mode");
1938:         halt_forever();
1939:     }
1940:     verify_kernel_cache_aliases(
1941:         boot_info,
1942:         &reader,
1943:         root,
1944:         config,
1945:         pat,
1946:         &mtrrs,
1947:         "kernel text",
1948:         segments.text.virtual_start,
1949:         segments.text.physical_start,
1950:         segments.text.virtual_end - segments.text.virtual_start,
1951:     );
1952:     verify_kernel_cache_aliases(
1953:         boot_info,
1954:         &reader,
1955:         root,
1956:         config,
1957:         pat,
1958:         &mtrrs,
1959:         "kernel rodata",
1960:         segments.rodata.virtual_start,
1961:         segments.rodata.physical_start,
1962:         segments.rodata.virtual_end - segments.rodata.virtual_start,
1963:     );
1964:     verify_kernel_cache_aliases(
1965:         boot_info,
1966:         &reader,
1967:         root,
1968:         config,
1969:         pat,
1970:         &mtrrs,
1971:         "kernel data",
1972:         segments.data.virtual_start,
1973:         segments.data.physical_start,
1974:         segments.data.virtual_end - segments.data.virtual_start,
1975:     );
1976:     probe_cloned_page_tables(
1977:         &mut boot_info.frame_allocator,
1978:         &boot_info.memory_map,
1979:         boot_info.hhdm_offset,
1980:         physical_address_bits,
1981:         boot_info.cpu_info.active_linear_address_bits,
1982:         &reader,
1983:         root,
1984:         config,
1985:         [
1986:             (
1987:                 "kernel text",
1988:                 segments.text.virtual_start,
1989:                 segments.text.physical_start,
1990:                 segments.text.virtual_end - segments.text.virtual_start,
1991:             ),
1992:             (
1993:                 "kernel rodata",
1994:                 segments.rodata.virtual_start,
1995:                 segments.rodata.physical_start,
1996:                 segments.rodata.virtual_end - segments.rodata.virtual_start,
1997:             ),
1998:             (
1999:                 "kernel data",
2000:                 segments.data.virtual_start,
2001:                 segments.data.physical_start,
2002:                 segments.data.virtual_end - segments.data.virtual_start,
2003:             ),
2004:             (
2005:                 "active boot stack",
2006:                 boot_info.boot_stack_virtual_start,
2007:                 boot_info.boot_stack_physical_start,
2008:                 boot_info.boot_stack_virtual_end - boot_info.boot_stack_virtual_start,
2009:             ),
2010:         ],
2011:     );
2012:     probe_candidate_page_tables(boot_info);
2013: }
