1324:         PageWalkOutcome, PatLayout, PAGE_SIZE,
1325:     };
1326: 
1327:     let physical_address_bits = cpu_info
1328:         .physical_address_bits
1329:         .ok_or("unknown physical width")?;
1330:     let pat_value = cpu_info.pat_msr_value.ok_or("PAT unavailable")?;
1331:     let pat = PatLayout::from_msr_value(pat_value).map_err(|_| "invalid PAT state")?;
1332:     let cache_layout = match &cpu_info.mtrr {
1333:         MtrrState::Captured(registers) => registers
1334:             .validated_layout(physical_address_bits)
1335:             .map_err(|_| "invalid MTRR state")?,
1336:         _ => return Err("MTRR state unavailable"),
1337:     };
1338:     let mut io_apics = madt.io_apics();
1339:     let io_apic = io_apics.next().ok_or("MADT has no I/O APIC")?;
1340:     if io_apics.next().is_some() {
1341:         return Err("multiple I/O APICs are unsupported by bootstrap routing");
1342:     }
1343: 
1344:     let pages = [
1345:         (LOCAL_APIC_VIRTUAL_ADDRESS, madt.local_apic_address),
1346:         (IO_APIC_VIRTUAL_ADDRESS, u64::from(io_apic.physical_address)),
1347:     ];
1348:     let permissions = PagePermissions {
1349:         writable: true,
1350:         executable: false,
1351:         user_accessible: false,
1352:     };
1353:     for (virtual_address, physical_address) in pages {
1354:         if !matches!(
1355:             candidate.walk(virtual_address),
1356:             Ok(PageWalkOutcome::NotPresent { .. })
1357:         ) {
1358:             return Err("reserved APIC virtual address is not unmapped");
1359:         }
1360:         let mapping = validate_mapping_range(
1361:             virtual_address,
1362:             physical_address,
1363:             PAGE_SIZE,
1364:             permissions,
1365:             Some(physical_address_bits),
1366:             cpu_info.active_linear_address_bits,
1367:         )
1368:         .map_err(|_| "APIC mapping range rejected")?;
1369:         let attributes = mapping
1370:             .select_cache_attributes(
1371:                 CachePolicy::Uncacheable,
1372:                 pat,
1373:                 &cache_layout,
1374:                 cpu_info.normal_caching,
1375:             )
1376:             .map_err(|_| "APIC page has no uniform UC cache policy")?;
1377:         if attributes.effective_type() != EffectiveMemoryType::Uncacheable {
1378:             return Err("APIC page is not effectively uncacheable");
1379:         }
1380:         // SAFETY: Both physical addresses come from the copied MADT, are used
1381:         // only as device registers, and will be mapped with the validated UC
1382:         // policy. The API enforces supervisor RW/NX mappings and non-ownership.
1383:         unsafe {
1384:             candidate
1385:                 .map_mmio_page(allocator, mapping, attributes)
1386:                 .map_err(|_| "APIC candidate mapping failed")?;
1387:         }
1388:         match candidate.walk(virtual_address) {
1389:             Ok(PageWalkOutcome::Mapped(translation))
1390:                 if translation.physical_address == physical_address
1391:                     && translation.page_size == PAGE_SIZE
1392:                     && translation.permissions == permissions
1393:                     && translation.pat_index == attributes.pat_index() => {}
1394:             _ => return Err("APIC candidate mapping did not verify"),
1395:         }
1396:     }
1397:     Ok((LOCAL_APIC_VIRTUAL_ADDRESS, IO_APIC_VIRTUAL_ADDRESS))
1398: }
