1400: // Error payloads provide boot diagnostics through the derived `Debug` output.
1401: #[allow(dead_code)]
1402: #[derive(Debug)]
1403: enum AcpiBootReadError {
1404:     PhysicalWidthUnknown,
1405:     PatUnavailable,
1406:     InvalidPat(rustix_kernel::paging::PatLayoutError),
1407:     InvalidMtrr(rustix_kernel::paging::MtrrError),
1408:     MtrrUnavailable,
1409:     NoVirtualWindow,
1410:     PageTableWalk,
1411:     Read(rustix_kernel::acpi::AcpiReadError<AcpiMappingError>),
1412: }
