1414: fn load_acpi_madt<'candidate, 'memory, 'map>(
1415:     candidate: &'candidate mut rustix_kernel::paging::CandidatePageTables<
1416:         'memory,
1417:         LimineHhdmCandidateMemory<'map>,
1418:     >,
1419:     allocator: &'candidate mut rustix_kernel::frame::FrameAllocator,
1420:     memory_map: &'map rustix_kernel::memory::MemoryMap,
1421:     cpu_info: &arch::x86_64::cpu::CpuInfo,
1422:     rsdp_physical_address: u64,
1423:     candidate_cr3: u64,
1424:     previous_cr3: u64,
1425: ) -> Result<rustix_kernel::acpi::Madt, AcpiBootReadError> {
1426:     use rustix_kernel::paging::{MtrrState, PageWalkOutcome, PatLayout};
1427: 
1428:     let physical_address_bits = cpu_info
1429:         .physical_address_bits
1430:         .ok_or(AcpiBootReadError::PhysicalWidthUnknown)?;
1431:     let pat_value = cpu_info
1432:         .pat_msr_value
1433:         .ok_or(AcpiBootReadError::PatUnavailable)?;
1434:     let pat = PatLayout::from_msr_value(pat_value).map_err(AcpiBootReadError::InvalidPat)?;
1435:     let cache_layout = match &cpu_info.mtrr {
1436:         MtrrState::Captured(registers) => registers
1437:             .validated_layout(physical_address_bits)
1438:             .map_err(AcpiBootReadError::InvalidMtrr)?,
1439:         _ => return Err(AcpiBootReadError::MtrrUnavailable),
1440:     };
1441: 
1442:     const WINDOW_BASE: u64 = 0xffff_c000_0000_0000;
1443:     const WINDOW_PAGES: u64 = 4096;
1444:     let mut virtual_address = WINDOW_BASE;
1445:     let mut window_found = false;
1446:     for _ in 0..WINDOW_PAGES {
1447:         match candidate.walk(virtual_address) {
1448:             Ok(PageWalkOutcome::NotPresent { .. }) => {
1449:                 window_found = true;
1450:                 break;
1451:             }
1452:             Ok(PageWalkOutcome::Mapped(_)) => {}
1453:             Err(_) => return Err(AcpiBootReadError::PageTableWalk),
1454:         }
1455:         virtual_address = virtual_address
1456:             .checked_add(rustix_kernel::paging::PAGE_SIZE)
1457:             .ok_or(AcpiBootReadError::NoVirtualWindow)?;
1458:     }
1459:     if !window_found {
1460:         return Err(AcpiBootReadError::NoVirtualWindow);
1461:     }
1462: 
1463:     let mut reader = CandidateAcpiReader {
1464:         candidate,
1465:         allocator,
1466:         memory_map,
1467:         physical_address_bits,
1468:         virtual_address_bits: cpu_info.active_linear_address_bits,
1469:         cache_layout,
1470:         pat,
1471:         normal_caching: cpu_info.normal_caching,
1472:         candidate_cr3,
1473:         previous_cr3,
1474:         virtual_address,
1475:     };
1476:     let mut scratch = [0u8; rustix_kernel::acpi::MAX_ACPI_STRUCTURE_SIZE];
1477:     rustix_kernel::acpi::read_madt(&mut reader, rsdp_physical_address, &mut scratch)
1478:         .map_err(AcpiBootReadError::Read)
1479: }
