1481: fn harden_kernel_hhdm_aliases(
1482:     candidate: &mut rustix_kernel::paging::CandidatePageTables<'_, LimineHhdmCandidateMemory<'_>>,
1483:     allocator: &mut rustix_kernel::frame::FrameAllocator,
1484:     memory_map: &rustix_kernel::memory::MemoryMap,
1485:     hhdm_offset: u64,
1486:     physical_address_bits: Option<u8>,
1487:     virtual_address_bits: u8,
1488:     segments: rustix_kernel::memory::KernelImageSegments,
1489:     reader: &impl rustix_kernel::paging::PageTableReader<
1490:         Error = rustix_kernel::memory::HhdmAddressError,
1491:     >,
1492:     inherited_root: rustix_kernel::paging::Cr3Root,
1493:     config: rustix_kernel::paging::PageWalkConfig,
1494: ) -> bool {
1495:     use rustix_kernel::paging::{
1496:         walk_virtual_address, PagePermissions, PageWalkOutcome, PAGE_SIZE,
1497:     };
1498: 
1499:     let image_segments = [
1500:         ("kernel text", segments.text, false),
1501:         ("kernel rodata", segments.rodata, false),
1502:         ("kernel data", segments.data, true),
1503:     ];
1504:     for (label, segment, writable) in image_segments {
1505:         let length = segment.physical_end - segment.physical_start;
1506:         let mut offset = 0;
1507:         while offset < length {
1508:             let Some(physical_address) = segment.physical_start.checked_add(offset) else {
1509:                 kprintln!(
1510:                     "kernel HHDM alias check failed: {} physical overflow",
1511:                     label
1512:                 );
1513:                 return false;
1514:             };
1515:             let alias = match memory_map.limine_hhdm_address(
1516:                 hhdm_offset,
1517:                 physical_address,
1518:                 PAGE_SIZE,
1519:                 physical_address_bits,
1520:                 virtual_address_bits,
1521:             ) {
1522:                 Ok(alias) => alias,
1523:                 Err(error) => {
1524:                     kprintln!(
1525:                         "kernel HHDM alias check failed: {} address: {:?}",
1526:                         label,
1527:                         error
1528:                     );
1529:                     return false;
1530:                 }
1531:             };
1532:             let source = match walk_virtual_address(reader, inherited_root, alias, config) {
1533:                 Ok(PageWalkOutcome::Mapped(translation)) => translation,
1534:                 result => {
1535:                     kprintln!(
1536:                         "kernel HHDM alias check failed: {} inherited walk: {:?}",
1537:                         label,
1538:                         result
1539:                     );
1540:                     return false;
1541:                 }
1542:             };
1543:             let permissions = PagePermissions {
1544:                 writable,
1545:                 executable: false,
1546:                 user_accessible: false,
1547:             };
1548:             if let Err(error) = candidate.set_inherited_page_permissions(
1549:                 allocator,
1550:                 alias,
1551:                 physical_address,
1552:                 permissions,
1553:             ) {
1554:                 kprintln!(
1555:                     "kernel HHDM alias check failed: {} protection: {:?}",
1556:                     label,
1557:                     error
1558:                 );
1559:                 return false;
1560:             }
1561:             match candidate.walk(alias) {
1562:                 Ok(PageWalkOutcome::Mapped(translation))
1563:                     if translation.physical_address == physical_address
1564:                         && translation.permissions == permissions
1565:                         && translation.pat_index == source.pat_index => {}
1566:                 result => {
1567:                     kprintln!(
1568:                         "kernel HHDM alias check failed: {} candidate walk: {:?}",
1569:                         label,
1570:                         result
1571:                     );
1572:                     return false;
1573:                 }
1574:             }
1575:             offset += PAGE_SIZE;
1576:         }
1577:     }
1578:     true
1579: }
