1799: #[cfg(feature = "probe-hhdm-frame")]
1800: fn probe_inherited_root(boot_info: &mut boot::BootInfo) {
1801:     use rustix_kernel::paging::inherited_cr3_root_hhdm_address;
1802: 
1803:     let root = match boot_info.inherited_cr3_root {
1804:         Ok(root) => root,
1805:         Err(error) => {
1806:             kprintln!(
1807:                 "inherited root probe failed: CR3 decode rejected: {:?}",
1808:                 error
1809:             );
1810:             halt_forever();
1811:         }
1812:     };
1813:     let address = match inherited_cr3_root_hhdm_address(
1814:         root,
1815:         &boot_info.memory_map,
1816:         boot_info.hhdm_offset,
1817:         boot_info.cpu_info.physical_address_bits,
1818:         boot_info.cpu_info.active_linear_address_bits,
1819:     ) {
1820:         Ok(address) => address,
1821:         Err(error) => {
1822:             kprintln!(
1823:                 "inherited root probe failed: HHDM validation rejected: {:?}",
1824:                 error
1825:             );
1826:             halt_forever();
1827:         }
1828:     };
1829:     let entries = address as *const u64;
1830:     let mut present_entries = 0;
1831:     // SAFETY: The complete root page was validated as bootloader-reclaimable
1832:     // and its HHDM range arithmetic was checked. The Limine base-revision-3
1833:     // contract maps that region; this read-only opt-in probe trusts that handoff.
1834:     unsafe {
1835:         for index in 0..512 {
1836:             if entries.add(index).read_volatile() & 1 != 0 {
1837:                 present_entries += 1;
1838:             }
1839:         }
1840:     }
1841:     kprintln!(
1842:         "inherited root HHDM probe passed: read 512 entries, {} present",
1843:         present_entries
1844:     );
1845:     let physical_address_bits = match boot_info.cpu_info.physical_address_bits {
1846:         Some(bits) => bits,
1847:         None => {
1848:             kprintln!("inherited page-table walk failed: physical width unknown");
1849:             halt_forever();
1850:         }
1851:     };
1852:     let reader = LimineHhdmPageTableReader {
