2015: #[cfg(feature = "probe-hhdm-frame")]
2016: fn probe_cloned_page_tables(
2017:     allocator: &mut rustix_kernel::frame::FrameAllocator,
2018:     memory_map: &rustix_kernel::memory::MemoryMap,
2019:     hhdm_offset: u64,
2020:     physical_address_bits: u8,
2021:     virtual_address_bits: u8,
2022:     source_reader: &impl rustix_kernel::paging::PageTableReader<
2023:         Error = rustix_kernel::memory::HhdmAddressError,
2024:     >,
2025:     source_root: rustix_kernel::paging::Cr3Root,
2026:     config: rustix_kernel::paging::PageWalkConfig,
2027:     spans: [(&str, u64, u64, u64); 4],
2028: ) {
2029:     use rustix_kernel::paging::CandidatePageTables;
2030: 
2031:     let mut memory = LimineHhdmCandidateMemory {
2032:         memory_map,
2033:         hhdm_offset,
2034:         physical_address_bits,
2035:         virtual_address_bits,
2036:     };
2037:     let mut candidate = match CandidatePageTables::new(allocator, &mut memory, config) {
2038:         Ok(candidate) => candidate,
2039:         Err(error) => {
2040:             kprintln!(
2041:                 "candidate clone probe failed to create root: {:?}",
2042:                 error.cause
2043:             );
2044:             if let Some(frame) = error.frame {
2045:                 release_probe_frame(allocator, frame);
2046:             }
2047:             halt_forever();
2048:         }
2049:     };
2050:     if let Err(error) = candidate.clone_inherited_hierarchy(allocator, source_reader, source_root) {
2051:         kprintln!("candidate clone probe failed: {:?}", error);
2052:         release_candidate_after_probe_failure(candidate, allocator);
2053:     }
2054:     for (label, virtual_start, physical_start, length) in spans {
2055:         if !candidate_span_matches_source(
2056:             &candidate,
2057:             source_reader,
2058:             source_root,
2059:             config,
2060:             virtual_start,
2061:             physical_start,
2062:             length,
2063:         ) {
2064:             kprintln!(
2065:                 "candidate clone probe failed: {} translation mismatch",
2066:                 label
2067:             );
2068:             release_candidate_after_probe_failure(candidate, allocator);
2069:         }
2070:     }
2071:     let table_count = candidate.table_count();
2072:     if let Err(failure) = candidate.release(allocator) {
2073:         kprintln!(
2074:             "candidate clone probe failed to release frames: {:?}",
2075:             failure
2076:         );
2077:         halt_forever();
2078:     }
2079:     kprintln!(
2080:         "candidate inherited-root clone probe passed: {} owned table pages preserve critical paths; CR3 unchanged",
2081:         table_count
2082:     );
2083: }
