2085: fn candidate_span_matches_source(
2086:     candidate: &rustix_kernel::paging::CandidatePageTables<'_, LimineHhdmCandidateMemory<'_>>,
2087:     source_reader: &impl rustix_kernel::paging::PageTableReader<
2088:         Error = rustix_kernel::memory::HhdmAddressError,
2089:     >,
2090:     source_root: rustix_kernel::paging::Cr3Root,
2091:     config: rustix_kernel::paging::PageWalkConfig,
2092:     virtual_start: u64,
2093:     physical_start: u64,
2094:     length: u64,
2095: ) -> bool {
2096:     use rustix_kernel::paging::{walk_virtual_address, PageWalkOutcome};
2097: 
2098:     let mut offset = 0;
2099:     while offset < length {
2100:         let Some(virtual_address) = virtual_start.checked_add(offset) else {
2101:             return false;
2102:         };
2103:         let Some(expected_physical) = physical_start.checked_add(offset) else {
2104:             return false;
2105:         };
2106:         let source_result =
2107:             walk_virtual_address(source_reader, source_root, virtual_address, config);
2108:         let candidate_result = candidate.walk(virtual_address);
2109:         let (source_translation, candidate_translation) = match (source_result, candidate_result) {
2110:             (Ok(PageWalkOutcome::Mapped(source)), Ok(PageWalkOutcome::Mapped(candidate))) => {
2111:                 (source, candidate)
2112:             }
2113:             (source, candidate) => {
2114:                 kprintln!(
2115:                     "candidate clone walk mismatch at {:#018x}: inherited={:?}, candidate={:?}",
2116:                     virtual_address,
2117:                     source,
2118:                     candidate
2119:                 );
2120:                 return false;
2121:             }
2122:         };
2123:         if !source_translation.same_effective_mapping(candidate_translation)
2124:             || candidate_translation.physical_address != expected_physical
2125:         {
2126:             kprintln!(
2127:                 "candidate clone translation mismatch at {:#018x}: inherited={:?}, candidate={:?}, expected PA={:#x}",
2128:                 virtual_address,
2129:                 source_translation,
2130:                 candidate_translation,
2131:                 expected_physical
2132:             );
2133:             return false;
2134:         }
2135:         let Some(next_offset) = offset.checked_add(rustix_kernel::paging::PAGE_SIZE) else {
2136:             return false;
2137:         };
2138:         offset = next_offset;
2139:     }
2140:     true
2141: }
