2143: #[cfg(feature = "probe-hhdm-frame")]
2144: fn probe_candidate_page_tables(boot_info: &mut boot::BootInfo) {
2145:     use rustix_kernel::paging::{
2146:         validate_mapping_range, CachePolicy, CandidatePageTables, PagePermissions, PageWalkOutcome,
2147:     };
2148: 
2149:     let Some(physical_address_bits) = boot_info.cpu_info.physical_address_bits else {
2150:         kprintln!("candidate page-table probe failed: physical width unknown");
2151:         halt_forever();
2152:     };
2153:     if !boot_info.cpu_info.nx_enabled || !boot_info.cpu_info.normal_caching {
2154:         kprintln!("candidate page-table probe failed: NXE or normal caching unavailable");
2155:         halt_forever();
2156:     }
2157:     let pat_value = boot_info
2158:         .cpu_info
2159:         .pat_msr_value
2160:         .expect("inherited cache-alias probe validated active PAT");
2161:     let pat = rustix_kernel::paging::PatLayout::from_msr_value(pat_value).unwrap_or_else(|error| {
2162:         kprintln!(
2163:             "candidate page-table probe failed: invalid PAT: {:?}",
2164:             error
2165:         );
2166:         halt_forever();
2167:     });
2168:     let registers = match &boot_info.cpu_info.mtrr {
2169:         rustix_kernel::paging::MtrrState::Captured(registers) => registers,
2170:         _ => {
2171:             kprintln!("candidate page-table probe failed: captured MTRR state unavailable");
2172:             halt_forever();
2173:         }
2174:     };
2175:     let mtrrs = match registers.validated_layout(physical_address_bits) {
2176:         Ok(mtrrs) => mtrrs,
2177:         Err(error) => {
2178:             kprintln!(
2179:                 "candidate page-table probe failed: invalid MTRR: {:?}",
2180:                 error
2181:             );
2182:             halt_forever();
2183:         }
2184:     };
2185:     let config = rustix_kernel::paging::PageWalkConfig {
2186:         levels: if boot_info.cpu_info.active_linear_address_bits == 57 {
2187:             5
2188:         } else {
2189:             4
2190:         },
2191:         physical_address_bits,
2192:         virtual_address_bits: boot_info.cpu_info.active_linear_address_bits,
2193:         nx_enabled: true,
2194:         page_2m_supported: true,
2195:         page_1g_supported: boot_info.cpu_info.has_1g_pages,
2196:     };
2197:     let virtual_address = 0xffff_9000_ffff_f000;
2198:     let permissions = PagePermissions {
2199:         writable: true,
2200:         executable: false,
2201:         user_accessible: false,
2202:     };
2203:     let frame = match boot_info.frame_allocator.allocate() {
2204:         Some(frame) => frame,
2205:         None => {
2206:             kprintln!("candidate page-table probe failed: no leaf frame available");
2207:             halt_forever();
2208:         }
2209:     };
2210:     let mapping = match validate_mapping_range(
2211:         virtual_address,
2212:         frame.address(),
2213:         rustix_kernel::paging::PAGE_SIZE,
2214:         permissions,
2215:         Some(physical_address_bits),
2216:         config.virtual_address_bits,
2217:     ) {
2218:         Ok(mapping) => mapping,
2219:         Err(error) => {
2220:             kprintln!(
2221:                 "candidate page-table probe failed: invalid mapping: {:?}",
2222:                 error
2223:             );
2224:             release_probe_frame(&mut boot_info.frame_allocator, frame);
2225:             halt_forever();
2226:         }
2227:     };
2228:     let cache_attributes = match mapping.select_cache_attributes(
2229:         CachePolicy::WriteBack,
2230:         pat,
2231:         &mtrrs,
2232:         boot_info.cpu_info.normal_caching,
2233:     ) {
2234:         Ok(attributes) => attributes,
2235:         Err(error) => {
2236:             kprintln!(
2237:                 "candidate page-table probe failed: cache policy: {:?}",
2238:                 error
2239:             );
2240:             release_probe_frame(&mut boot_info.frame_allocator, frame);
2241:             halt_forever();
2242:         }
2243:     };
2244: 
2245:     let mut memory = LimineHhdmCandidateMemory {
2246:         memory_map: &boot_info.memory_map,
2247:         hhdm_offset: boot_info.hhdm_offset,
2248:         physical_address_bits,
2249:         virtual_address_bits: boot_info.cpu_info.active_linear_address_bits,
2250:     };
2251:     let mut candidate =
2252:         match CandidatePageTables::new(&mut boot_info.frame_allocator, &mut memory, config) {
2253:             Ok(candidate) => candidate,
2254:             Err(error) => {
2255:                 kprintln!(
2256:                     "candidate page-table probe failed to create root: {:?}",
2257:                     error.cause
2258:                 );
2259:                 release_probe_frame(&mut boot_info.frame_allocator, frame);
2260:                 if let Some(root_frame) = error.frame {
2261:                     release_probe_frame(&mut boot_info.frame_allocator, root_frame);
2262:                 }
2263:                 halt_forever();
2264:             }
2265:         };
2266:     let root = candidate.root_physical_address();
2267:     let frame_address = frame.address();
2268:     if let Err(failure) = candidate.map_owned_page(
2269:         &mut boot_info.frame_allocator,
2270:         frame,
2271:         mapping,
2272:         cache_attributes,
2273:     ) {
2274:         kprintln!(
2275:             "candidate page-table probe failed to map leaf: {:?}",
2276:             failure.cause
2277:         );
2278:         release_probe_frame(&mut boot_info.frame_allocator, failure.frame);
2279:         release_candidate_after_probe_failure(candidate, &mut boot_info.frame_allocator);
2280:     }
2281: 
2282:     let walk = candidate.walk(virtual_address);
2283:     let returned_frame = match candidate.unmap_owned_page(virtual_address) {
2284:         Ok(frame) => frame,
2285:         Err(error) => {
2286:             kprintln!(
2287:                 "candidate page-table probe failed to unmap leaf: {:?}",
2288:                 error
2289:             );
2290:             release_candidate_after_probe_failure(candidate, &mut boot_info.frame_allocator);
2291:         }
2292:     };
2293:     let translation_valid = match &walk {
2294:         Ok(PageWalkOutcome::Mapped(translation)) => {
2295:             translation.physical_address == frame_address
2296:                 && translation.page_size == rustix_kernel::paging::PAGE_SIZE
2297:                 && translation.permissions == permissions
2298:                 && translation.pat_index == cache_attributes.pat_index()
2299:         }
2300:         _ => false,
2301:     };
2302:     if returned_frame.address() != frame_address {
2303:         kprintln!("candidate page-table probe failed: unmap returned the wrong frame");
2304:         release_probe_frame(&mut boot_info.frame_allocator, returned_frame);
2305:         release_candidate_after_probe_failure(candidate, &mut boot_info.frame_allocator);
2306:     }
2307:     release_probe_frame(&mut boot_info.frame_allocator, returned_frame);
2308:     if !translation_valid {
2309:         kprintln!(
2310:             "candidate page-table probe failed: candidate walk: {:?}",
2311:             walk
2312:         );
2313:         release_candidate_after_probe_failure(candidate, &mut boot_info.frame_allocator);
2314:     }
2315:     if let Err(failure) = candidate.release(&mut boot_info.frame_allocator) {
2316:         kprintln!(
2317:             "candidate page-table probe failed to release frames: {:?}",
2318:             failure
2319:         );
2320:         halt_forever();
2321:     }
2322:     kprintln!(
2323:         "candidate page-table probe passed: mapped, walked, unmapped, and released root {:#x}; CR3 unchanged",
2324:         root.expect("candidate retains root until release")
2325:     );
2326: }
