2338: #[cfg(feature = "probe-hhdm-frame")]
2339: fn verify_inherited_mapping(
2340:     reader: &impl rustix_kernel::paging::PageTableReader<
2341:         Error = rustix_kernel::memory::HhdmAddressError,
2342:     >,
2343:     root: rustix_kernel::paging::Cr3Root,
2344:     config: rustix_kernel::paging::PageWalkConfig,
2345:     label: &str,
2346:     virtual_start: u64,
2347:     physical_start: u64,
2348:     length: u64,
2349: ) {
2350:     use rustix_kernel::paging::{walk_virtual_address, PageWalkOutcome};
2351: 
2352:     let mut offset = 0;
2353:     let mut pages = 0;
2354:     let mut first_translation: Option<rustix_kernel::paging::PageTranslation> = None;
2355:     let mut permissions_uniform = true;
2356:     let mut pat_index_uniform = true;
2357:     while offset < length {
2358:         let virtual_address = match virtual_start.checked_add(offset) {
2359:             Some(address) => address,
2360:             None => {
2361:                 kprintln!("inherited mapping probe failed: {} virtual overflow", label);
2362:                 halt_forever();
2363:             }
2364:         };
2365:         let expected_physical = match physical_start.checked_add(offset) {
2366:             Some(address) => address,
2367:             None => {
2368:                 kprintln!(
2369:                     "inherited mapping probe failed: {} physical overflow",
2370:                     label
2371:                 );
2372:                 halt_forever();
2373:             }
2374:         };
2375:         let translation = match walk_virtual_address(reader, root, virtual_address, config) {
2376:             Ok(PageWalkOutcome::Mapped(translation)) => translation,
2377:             Ok(PageWalkOutcome::NotPresent { level }) => {
2378:                 if level == rustix_kernel::paging::PageLevel::Pml4 {
2379:                     let pml4_index = ((virtual_address >> 39) & 0x1ff) as u16;
2380:                     let root_entry = reader.read_entry(root.physical_address(), pml4_index);
2381:                     kprintln!(
2382:                         "inherited mapping PML4 detail: VA={:#018x}, index={}, root={:#x}, entry={:?}",
2383:                         virtual_address,
2384:                         pml4_index,
2385:                         root.physical_address(),
2386:                         root_entry
2387:                     );
2388:                 }
2389:                 kprintln!(
2390:                     "inherited mapping probe failed: {} absent at {:?}",
2391:                     label,
2392:                     level
2393:                 );
2394:                 halt_forever();
2395:             }
2396:             Err(error) => {
2397:                 kprintln!("inherited mapping probe failed: {}: {:?}", label, error);
2398:                 halt_forever();
2399:             }
2400:         };
2401:         if translation.physical_address != expected_physical {
2402:             kprintln!(
2403:                 "inherited mapping probe failed: {} {:#018x} mapped to {:#018x}, expected {:#018x}",
2404:                 label,
2405:                 virtual_address,
2406:                 translation.physical_address,
2407:                 expected_physical
2408:             );
2409:             halt_forever();
2410:         }
2411:         if let Some(first) = first_translation {
2412:             permissions_uniform &= translation.permissions == first.permissions;
2413:             pat_index_uniform &= translation.pat_index == first.pat_index;
2414:         } else {
2415:             first_translation = Some(translation);
2416:         }
2417:         pages += 1;
2418:         offset += rustix_kernel::paging::PAGE_SIZE;
2419:     }
2420:     if let Some(first) = first_translation {
2421:         kprintln!(
2422:             "inherited mapping probe passed: {} ({} pages), first permissions={:?}, PAT index={}, leaf size={}, uniform permissions={}, uniform PAT index={}",
2423:             label,
2424:             pages,
2425:             first.permissions,
2426:             first.pat_index,
2427:             first.page_size,
2428:             permissions_uniform,
2429:             pat_index_uniform
2430:         );
2431:     }
2432: }
