2436:     boot_info: &boot::BootInfo,
2437:     reader: &impl rustix_kernel::paging::PageTableReader<
2438:         Error = rustix_kernel::memory::HhdmAddressError,
2439:     >,
2440:     root: rustix_kernel::paging::Cr3Root,
2441:     config: rustix_kernel::paging::PageWalkConfig,
2442:     pat: rustix_kernel::paging::PatLayout,
2443:     mtrrs: &rustix_kernel::paging::ValidatedMtrrLayout,
2444:     label: &str,
2445:     kernel_virtual_start: u64,
2446:     physical_start: u64,
