697: fn is_valid_pointer<T>(pointer: *const T, virtual_address_bits: u8) -> bool {
698:     let start = pointer as usize;
699:     let Some(end) = start.checked_add(size_of::<T>()) else {
700:         return false;
701:     };
702:     !pointer.is_null()
703:         && start & (align_of::<T>() - 1) == 0
704:         && is_canonical_virtual_address(start as u64, virtual_address_bits)
705:         && is_canonical_virtual_address((end - 1) as u64, virtual_address_bits)
706: }

