172: /// Install a private kernel GDT/TSS, exception gates, and device IRQ gates.
173: ///
174: /// The bootstrap runs with maskable interrupts disabled. This routine leaves
175: /// them disabled and does not modify CR3 or the inherited page-table hierarchy.
176: pub fn initialize() {
177:     // SAFETY: Single-core bootstrap ownership; the descriptor tables are private
178:     // static storage and are initialized before any gate is loaded.
179:     unsafe {
180:         asm!("cli", options(nomem, nostack));
181:         initialize_tss();
182:         initialize_gdt();
183:         initialize_idt();
184:     }
185: }
186: 
187: unsafe fn initialize_tss() {
188:     let ring0_stack = core::ptr::addr_of_mut!(RING0_STACK).cast::<u8>();
189:     let double_fault_stack = core::ptr::addr_of_mut!(DOUBLE_FAULT_STACK).cast::<u8>();
190:     // SAFETY: These pointers refer to the ends of distinct, aligned static stacks.
191:     let ring0_top = unsafe { ring0_stack.add(STACK_SIZE) } as u64;
192:     // SAFETY: These pointers refer to the ends of distinct, aligned static stacks.
193:     let double_fault_top = unsafe { double_fault_stack.add(STACK_SIZE) } as u64;
194:     let tss = core::ptr::addr_of_mut!(TSS);
195: 
196:     // The architectural TSS fields are packed; use unaligned raw writes rather
197:     // than creating references to their potentially unaligned storage.
198:     unsafe {
199:         core::ptr::addr_of_mut!((*tss).rsp0).write_unaligned(ring0_top);
200:         core::ptr::addr_of_mut!((*tss).ist1).write_unaligned(double_fault_top);
201:     }
202: }
203: 
204: unsafe fn initialize_gdt() {
205:     let tss_base = core::ptr::addr_of!(TSS) as u64;
206:     let tss_limit = (size_of::<TaskStateSegment>() - 1) as u64;
207:     let low = (tss_limit & 0xffff)
208:         | ((tss_base & 0x00ff_ffff) << 16)
209:         | (TSS_DESCRIPTOR_TYPE << 40)
210:         | ((tss_limit & 0x000f_0000) << 32)
211:         | ((tss_base & 0xff00_0000) << 32);
212:     let high = tss_base >> 32;
213: 
214:     unsafe {
215:         core::ptr::addr_of_mut!(GDT[0]).write(0);
216:         core::ptr::addr_of_mut!(GDT[1]).write(0x00af_9a00_0000_ffff);
217:         core::ptr::addr_of_mut!(GDT[2]).write(0x00cf_9200_0000_ffff);
218:         core::ptr::addr_of_mut!(GDT[3]).write(low);
219:         core::ptr::addr_of_mut!(GDT[4]).write(high);
220:     }
221: 
222:     let gdtr = DescriptorTablePointer {
223:         limit: (size_of::<[u64; 5]>() - 1) as u16,
224:         base: core::ptr::addr_of!(GDT) as u64,
225:     };
226:     // SAFETY: `GDT` and its TSS descriptor are initialized and remain live.
227:     unsafe { rustix_load_gdt(&gdtr) };
228: }
229: 
230: unsafe fn initialize_idt() {
231:     let idt_entries = core::ptr::addr_of_mut!(IDT.0).cast::<IdtEntry>();
232:     let stubs = core::ptr::addr_of!(exception_stub_table).cast::<usize>();
233: 
234:     for vector in 0..EXCEPTION_COUNT {
235:         // SAFETY: The assembly table contains exactly 32 stub addresses.
236:         let handler = unsafe { stubs.add(vector).read() } as u64;
237:         let ist = if vector == 8 { 1 } else { 0 };
238:         // SAFETY: `vector` is bounded by the statically allocated 256-entry IDT.
239:         unsafe {
240:             idt_entries
241:                 .add(vector)
242:                 .write(IdtEntry::interrupt_gate(handler, ist));
243:         }
244:     }
245: 
246:     let irq_stubs = core::ptr::addr_of!(irq_stub_table).cast::<usize>();
247:     for vector in IRQ_FIRST_VECTOR..=IRQ_LAST_VECTOR {
248:         // SAFETY: The assembly table contains one stub for each allocated vector.
249:         let handler = unsafe { irq_stubs.add(vector - IRQ_FIRST_VECTOR).read() } as u64;
250:         // SAFETY: `vector` is bounded by the statically allocated 256-entry IDT.
251:         unsafe {
252:             idt_entries
253:                 .add(vector)
254:                 .write(IdtEntry::interrupt_gate(handler, 0));
255:         }
256:     }
257:     // SAFETY: The final table entry is the dedicated 0xff spurious-IRQ stub.
258:     let spurious_handler = unsafe { irq_stubs.add(IRQ_VECTOR_COUNT).read() } as u64;
259:     // SAFETY: The APIC spurious vector is a valid IDT index.
260:     unsafe {
261:         idt_entries
262:             .add(APIC_SPURIOUS_VECTOR)
263:             .write(IdtEntry::interrupt_gate(spurious_handler, 0));
264:     }
265: 
266:     let idtr = DescriptorTablePointer {
267:         limit: (size_of::<IdtTable>() - 1) as u16,
268:         base: core::ptr::addr_of!(IDT) as u64,
269:     };
270:     // SAFETY: Every architectural exception gate is initialized in static storage.
271:     unsafe { asm!("lidt [{}]", in(reg) &idtr, options(readonly, nostack, preserves_flags)) };
272: }
