14:     unsafe {
15:         super::io::write_u8(COM1 + 1, 0x00);
16:         super::io::write_u8(COM1 + 3, 0x80);
17:         super::io::write_u8(COM1, 0x03);
18:         super::io::write_u8(COM1 + 1, 0x00);
19:         super::io::write_u8(COM1 + 3, 0x03);
20:         super::io::write_u8(COM1 + 2, 0xc7);
21:         super::io::write_u8(COM1 + 4, 0x0b);
22:     }
23:     INITIALIZED.store(true, Ordering::Release);
24: }
