35:     if !INITIALIZED.load(Ordering::Acquire) {
36:         return None;
37:     }
38:     if RX_INTERRUPT_MODE.load(Ordering::Acquire) {
39:         return rustix_kernel::input::UART_INPUT.try_pop();
40:     }
